do $guard$ begin
 if (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate)<>43435 then raise exception 'baseline changed'; end if;
 if (select count(*) from low_precision t join public.safety_spots p using(source_key) where p.active and not p.duplicate_candidate and p.facility_type='aed' and p.geocode_source ilike '%Geolonia%' and abs(p.latitude-t.latitude)<1e-7 and abs(p.longitude-t.longitude)<1e-7)<>382 then raise exception 'evidence changed'; end if;
end $guard$;
update public.safety_spots p set active=false,quality_status='rough' from low_precision t where p.source_key=t.source_key;
update public.safety_spots_nationwide_stage s set review_decision='hold',review_reason='位置情報精度の再検証で町・市の代表点と一致。番地精度ではないため公開停止',review_next_action='公式施設座標または実際の位置情報レベル8を確認して再審査',reviewed_at=now() from low_precision t where s.source_key=t.source_key;
do $guard$ begin
 if (select count(*) from low_precision t join public.safety_spots p using(source_key) where p.active)<>0 then raise exception 'still active'; end if;
 if (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate)<>43053 then raise exception 'post-count'; end if;
end $guard$;
select 382 as held,(select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate) as public_aed;
commit;
